// on; anything else (including unset) keeps real mode, so the flag
// is fail-safe: a missing var can never simulate what an operator
// believes is live, and an unset var can never be read as 'simulate'
// either - only the three explicit spellings count. Simulated mode
// replaces ONLY the external API layer inside the drivers (token
// refresh, host photo upload, wall.post + wall.getById/wall.delete,
// LinkedIn assets.registerUpload + binary PUT + ugcPosts + DELETE):
// the claim -> media resolve -> ledger ->
// status file -> registry -> Telegram pipeline runs end-to-end
// unchanged, and the PUBLISH_PLATFORMS gate above stays
// authoritative. Every artifact is marked - ledger status
// 'simulated' + simulated:true, registry status 'simulated',
// per-file status 'simulated', the summary line says SIMULATED -
// and the synthetic external_id carries a 'sim-' prefix so no
// reader can ever feed it to a real delete/republish path as if it
// were a live post id.
// SYNC-BEGIN: publish-simulate
const SIMULATE = ['1', 'true', 'yes'].indexOf(
  String(ENV('PUBLISH_SIMULATE') || '').trim().toLowerCase()) >= 0;
// SYNC-END: publish-simulate
// SYNC-BEGIN: publish-post-link
// operator-facing post reference for the tick summary (issue #43): a
// VK external_id '<owner>_<post>' parses straight into the public
// wall URL the operator can click ('https://vk.com/wall<owner>_<post>');
// a LinkedIn share URN is NOT a URL, so it renders as a labeled URN
// instead of a fake link. Simulated ids ('sim-' prefix) stay literal -
// there is no page behind them; the ' (sim id)' tail just re-marks it.
const postLink = (ext) => {
  const e = String(ext || '');
  if (!e) return '';
  if (/^sim-/.test(e)) return e + ' (sim id)';
  if (/^-?\d+_\d+$/.test(e)) return 'https://vk.com/wall' + e;
  if (/^urn:li:/.test(e)) return 'LinkedIn post URN: ' + e;
  return e;
};
// SYNC-END: publish-post-link
for (const d of [Q, Q + '/done', Q + '/failed', Q + '/skipped',
  Q + '/processing', LOGD, STATE]) {
  try { fs.mkdirSync(d, { recursive: true }); } catch (e) {}
}
const token = ENV('TELEGRAM_BOT_TOKEN');
// operator chat_id is pinned config: TELEGRAM_CHAT_ID env first, the
// tg.json written by sp-tg-setup as compat fallback - never learned
// from incoming webhook updates (untrusted source)
let chatId = ENV('TELEGRAM_CHAT_ID') || null;
if (!chatId) {
  try { chatId = JSON.parse(fs.readFileSync(STATE + '/tg.json', 'utf8')).chat_id; } catch (e) {}
}
const tg = (method, body) => {
  // SYNC-BEGIN: tg-timeout
  return this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.telegram.org/bot' + token + '/' + method,
    body: body || {},
    json: true,
    // explicit timeout like vkCall below: an unbounded request that
    // hangs on api.telegram.org would stall the tick while it holds a
    // processing/ claim - stuck-claim recovery then reclassifies the
