};
const http = (o) => this.helpers.httpRequest(o);
// best-effort by contract: a transient FS failure (EMFILE, quota,
// remount) must NEVER propagate out of log() - several call sites sit
// inside failure paths (the claim catch, mv()'s logParked and
// move-failed logs, the skipped/bad-json notes) where a throw would
// escape the per-file loop and abort the whole tick mid-run,
// stranding a live claim in processing/ until the ~10min recovery
// marks it maybe_live. Same discipline the mkdirErrs flush and
// ledger() below already follow: logging never breaks the flow.
const log = (r) => {
  try {
    fs.appendFileSync(LOGD + '/publish.jsonl',
      JSON.stringify({ ts: new Date().toISOString(), ...r }) + '\n');
  } catch (e) {}
};
// SYNC-BEGIN: media-resolve
const MEDIA_ROOT = '/home/node/materials';
const MEDIA_ROOT_REAL = (() => {
  try { return fs.realpathSync(MEDIA_ROOT); } catch (e) { return MEDIA_ROOT; }
})();
// moderation-draft is a public webhook, so media[] must never resolve
// outside the read-only materials/ mount: a bare absolute host path
// (/etc/..., a DB file) or a symlink inside materials/ pointing out
// would otherwise be read and sent back over Telegram
const underRoot = (p) => {
  try {
    const rp = fs.realpathSync(p);
    return rp === MEDIA_ROOT_REAL || rp.startsWith(MEDIA_ROOT_REAL + '/');
  } catch (e) { return false; }
};
