// bare filenames - resolve them against the read-only mount.
const resolveMedia = (s) => {
  const p = String(s || '');
  if (!p) return null;
  const cands = [];
  const m = p.match(/(?:^|\/)materials\/(.+)$/);
  if (m) cands.push(MEDIA_ROOT + '/' + m[1]);
  if (p.startsWith('/')) cands.push(p);
  const base = p.split('/').pop();
  cands.push(MEDIA_ROOT + '/photos/' + base, MEDIA_ROOT + '/' + base);
  for (const c of cands) {
    if (fs.existsSync(c) && underRoot(c)) return c;
  }
  return null;
};
const mimeOf = (p) => (/\.png$/i.test(p) ? 'image/png'
  : /\.webp$/i.test(p) ? 'image/webp' : 'image/jpeg');
// SYNC-END: media-resolve
// post registry (issue #12, docs/post-registry-design.md): one
// append-only JSONL lifecycle log every stage writes to. Fail-open
// by contract - a broken state dir, a torn write or an oversized
// event must never block moderation or publish: errors are
// swallowed into this node's own log() and the flow moves on.
// event_id is a deterministic sha1 over the TRANSITION identity
// (post_id|platform|stage|status|writer - deliberately NOT the
// timestamp): a retried transition recomputes ts and dedups to one
// event, while the reader's last-occurrence-wins fold still lands
// on the latest fields. n8n Code nodes only require('fs'), so the
// sha1 rides along inline - same 'no crypto' discipline as the
// sibling nodes' padded compares and FNV hashes.
// SYNC-BEGIN: registry-event
const registryEvent = (fields) => {
  try {
    if (!fields || !fields.post_id) return;
    const sha1hex = (s) => {
      const bytes = unescape(encodeURIComponent(String(s)));
      const ml = bytes.length;
      const ww = [];
      for (let i = 0; i < ml; i++) {
        ww[i >> 2] = (ww[i >> 2] || 0) |
          (bytes.charCodeAt(i) << (24 - (i % 4) * 8));
      }
      ww[ml >> 2] = (ww[ml >> 2] || 0) |
        (0x80 << (24 - (ml % 4) * 8));
      const wl = (((ml + 8) >> 6) << 4) + 16;
      ww[wl - 1] = ml * 8;
      let h0 = 1732584193, h1 = -271733879, h2 = -1732584194,
        h3 = 271733878, h4 = -1009589776;
      for (let i = 0; i < wl; i += 16) {
        const w = new Array(80);
        for (let j = 0; j < 16; j++) w[j] = ww[i + j] || 0;
        for (let j = 16; j < 80; j++) {
          const x = w[j - 3] ^ w[j - 8] ^ w[j - 14] ^ w[j - 16];
          w[j] = (x << 1) | (x >>> 31);
        }
        let a = h0, b = h1, c = h2, d = h3, e = h4;
        for (let j = 0; j < 80; j++) {
          const f = j < 20 ? (b & c) | (~b & d)
            : j < 40 ? b ^ c ^ d
            : j < 60 ? (b & c) | (b & d) | (c & d)
            : b ^ c ^ d;
          const k = j < 20 ? 1518500249
            : j < 40 ? 1859775393
            : j < 60 ? -1894007588 : -899497514;
          const t = (((a << 5) | (a >>> 27)) + f + e + k + w[j]) | 0;
          e = d; d = c; c = ((b << 30) | (b >>> 2)) | 0; b = a; a = t;
        }
        h0 = (h0 + a) | 0; h1 = (h1 + b) | 0;
        h2 = (h2 + c) | 0; h3 = (h3 + d) | 0;
        h4 = (h4 + e) | 0;
      }
      return [h0, h1, h2, h3, h4]
        .map((h) => ('00000000' + (h >>> 0).toString(16)).slice(-8))
        .join('');
    };
    const ev = {
      schema_v: 1,
      post_id: String(fields.post_id),
      draft_id: String(fields.draft_id || ''),
      platform: String(fields.platform || ''),
      stage: String(fields.stage || ''),
      status: String(fields.status || ''),
      ts: new Date().toISOString(),
      writer: String(fields.writer || '')
    };
    ev.event_id = sha1hex(ev.post_id + '|' + ev.platform + '|' +
      ev.stage + '|' + ev.status + '|' + ev.writer);
    if (fields.error) ev.error = String(fields.error).slice(0, 300);
    if (fields.maybe_live === true) ev.maybe_live = true;
    if (Array.isArray(fields.external_ids) && fields.external_ids.length) {
      ev.external_ids = fields.external_ids.map(String);
    }
    if (fields.published_at) ev.published_at = String(fields.published_at);
    // O_APPEND keeps concurrent single-line appends intact only
    // while a line stays under PIPE_BUF (4KB, ~3.5KB used as the
    // conservative cap). Shrink in the spec'd order - error text
    // first, external_ids to its first element, then maybe_live;
    // the required fields and published_at are never dropped.
    let oversized = false;
    let line = JSON.stringify(ev) + '\n';
    if (line.length > 3500) {
      oversized = true;
      if (ev.error) ev.error = ev.error.slice(0, 120);
      line = JSON.stringify(ev) + '\n';
    }
    if (line.length > 3500 && ev.external_ids &&
        ev.external_ids.length > 1) {
      ev.external_ids = ev.external_ids.slice(0, 1);
      line = JSON.stringify(ev) + '\n';
    }
    if (line.length > 3500 && ev.maybe_live) {
      delete ev.maybe_live;
      line = JSON.stringify(ev) + '\n';
    }
    if (oversized) {
      try {
        log({ action: 'registry_event_oversized',
          post_id: ev.post_id, stage: ev.stage });
      } catch (e) {}
    }
    fs.mkdirSync('/home/node/.n8n/state/registry', { recursive: true });
    fs.appendFileSync('/home/node/.n8n/state/registry/events.jsonl', line);
  } catch (e) {
    try {
      log({ action: 'registry_append_failed',
        error: String(e).slice(0, 150) });
    } catch (e2) {}
  }
};
// SYNC-END: registry-event
// atomic state writes: tmp file + rename, so a crash mid-write cannot
// leave a torn vk_status.json / vk_token.json behind. The tmp name is
// UNIQUE per call - a fixed 'p + .tmp' lets two overlapping ticks open
// the same staging file: the shorter second writeSync leaves the tail
// of the first payload behind, and the torn JSON is then renamed over
// the real state file. Same timestamp+random suffix discipline as the
// sibling writeJsonAtomic in sp-tg-moderation (no process.pid - the
// task runner sandbox does not expose `process`).
// SYNC: sibling copies live in Handle TG Update, Prepare Draft and
// Compose Message (sp-tg-moderation), Generate Drafts
// (sp-content-gen) and Resolve Chat + Webhook (sp-tg-setup) - this
// is the hardened 0o600 variant, the others write plain. n8n Code
// nodes cannot share a prelude - replicate any fix to every copy.
// SYNC-BEGIN: write-json-atomic-hardened
const writeJsonAtomic = (p, obj) => {
  const tmp = p + '.tmp-' + Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 8);
  // the state dir is bind-mounted next to the SQLite DB and logs -
  // keep cached credentials (vk_token.json) and status files
  // owner-only. Apply the mode at creation: a writeFileSync +
  // later chmodSync leaves a window where a tmp file holding a live
  // VK token is group/world-readable under the default umask. The
  // chmod backstop covers reusing an older loose tmp file (the open
  // mode only applies to files this call creates).
  const fd = fs.openSync(tmp, 'w', 0o600);
  try {
    // writeSync may legally return a short byte count (interrupted
    // write, ENOSPC partial) - loop until the whole payload is on
    // disk before the rename publishes it, or a torn JSON lands over
    // a good state file. Buffer (not the string form) so multi-byte
    // chars cannot corrupt the offset math.
    const buf = Buffer.from(JSON.stringify(obj), 'utf8');
    let off = 0;
    while (off < buf.length) {
      off += fs.writeSync(fd, buf, off, buf.length - off);
    }
  } finally {
    fs.closeSync(fd);
  }
  try { fs.chmodSync(tmp, 0o600); } catch (e) {}
  fs.renameSync(tmp, p);
};
// SYNC-END: write-json-atomic-hardened
// issue #70: the stale-draft GC below re-reads and flips draft files
// the operator can be deciding on in a parallel Handle TG Update
// execution - the re-read/pin-check/write must serialize with those
// callbacks under the same per-draft lock, or an auto-reject can
// clobber a same-tick Approve (and its queue file) between the GC's
// own read and write. withLock serializes them under a tokened
// state/locks/<key>.lock file: EEXIST = live lock = a thrown
// LockBusyError (.lockBusy = true) - the GC just skips that draft
// and the next tick retries; an expired or unreadable lock is stolen
// via tmp+rename and proven by re-read; release re-reads and unlinks
// only our own token. No tg()/HTTP call ever runs inside fn() - the
// keyboard strip above stays outside the lock.
// SYNC: identical copies live in Prepare Draft and Handle TG Update
// (sp-tg-moderation). n8n Code nodes cannot share a prelude -
// replicate any fix to every copy by hand.
// SYNC-BEGIN: file-lock
const LOCKS_DIR = STATE + '/locks';
try { fs.mkdirSync(LOCKS_DIR, { recursive: true }); } catch (e) {}
const lockBusyError = () => {
  const e = new Error('state lock busy');
  e.name = 'LockBusyError';
  e.lockBusy = true;
  return e;
};
const withLock = (key, ttlMs, fn) => {
  const lp = LOCKS_DIR + '/' + key + '.lock';
  // no crypto/process in Code nodes - timestamp+random like the
  // writeJsonAtomic tmp names is entropy enough for a lock token
  const mine = Date.now().toString(36) + '-' +
    Math.random().toString(36).slice(2, 10);
  const claim = JSON.stringify({ token: mine, exp: Date.now() + ttlMs });
  let held = false;
  try {
    fs.writeFileSync(lp, claim, { flag: 'wx', mode: 0o600 });
    held = true;
  } catch (e) {
    if (!e || e.code !== 'EEXIST') throw e;
    // only a PROVEN-live lock (readable, exp in the future) makes us
    // busy - anything else is stolen, then verified by re-read
    // because a competing stealer may have won the rename
    let cur = null;
    try { cur = JSON.parse(fs.readFileSync(lp, 'utf8')); } catch (e2) {}
    if (cur && Number.isFinite(Number(cur.exp)) &&
        Date.now() <= Number(cur.exp)) {
      throw lockBusyError();
    }
    const tmp = lp + '.tmp-' + mine;
    try {
      fs.writeFileSync(tmp, claim, { mode: 0o600 });
      fs.renameSync(tmp, lp);
      held = JSON.parse(fs.readFileSync(lp, 'utf8')).token === mine;
    } catch (e3) { held = false; }
    try { fs.unlinkSync(tmp); } catch (e4) {}
    if (!held) throw lockBusyError();
  }
  try {
    return fn();
  } finally {
    if (held) {
      try {
        const cur = JSON.parse(fs.readFileSync(lp, 'utf8'));
        if (cur && cur.token === mine) fs.unlinkSync(lp);
      } catch (e5) {
        // release failures never propagate: a leaked lock expires
        // on its own; ENOENT just means it was already removed
        if (!e5 || e5.code !== 'ENOENT') {
          try {
            if (typeof log === 'function') {
              log({ action: 'lock-release-failed', key: key,
