  // (observed live: a wall.post transport throw surfaced exactly so).
  // Prefer .message, then a bounded JSON dump, before String(). The
  // token masking below runs on whichever text came out, so a config
  // dump carrying the request body/headers is still safe.
  let str;
  if (s instanceof Error) str = String(s);
  else if (s && typeof s === 'object') {
    if (s.message) str = String(s.message);
    else {
      try { str = JSON.stringify(s); } catch (je) { str = String(s); }
