// the VK headline (and vice versa)
const liStatus = (s, reason, file) => {
  liTickFiles.push({ file: file || '', status: s, reason: reason || '' });
  try {
    const now = new Date().toISOString();
    writeJsonAtomic(LI_STATUS, {
      status: s, ts: now, last_tick: now, file: file || '',
      reason: reason || '', files: liTickFiles
    });
